      c.train = c.train || { str: 0, agi: 0, end: 0, vit: 0, wil: 0 };
      c.train[key2] = (c.train[key2] || 0) + amt;
      c.recent = c.recent || {};
      c.recent[key2] = (c.recent[key2] || 0) * 0.995 + amt;
