        g.ui.toast("NEW TECHNIQUE", d.name, "#ffab91");
        g.log(`Your mastery of the ${FRUITS[c.fruit].name} reveals a new technique: ${d.name}. Put it on your hotbar from the Skills tab.`, "#ffab91");
