        if (c.attrs[pick5] >= ATTR_CAP) pick5 = KEYS.find((k) => c.attrs[k] < ATTR_CAP) || pick5;
        c.attrs[pick5] = Math.min(ATTR_CAP, c.attrs[pick5] + 1);
