  var SeaKingBrain = class {
    constructor(opts) {
      this.t = 1 + Math.random();
      this.opts = opts;
      this.submerged = false;
    }
    update(k, dt, game) {
      const p = game.player;
      const tgtShip = p.mode === "sail" && p.ship && !p.ship.sunk ? p.ship : null;
      let tx = p.x, ty = p.y;
      if (tgtShip) {
        const c = Math.cos(tgtShip.heading), sn = Math.sin(tgtShip.heading), L2 = tgtShip.def.length;
        const ox = game.world.dx(tgtShip.x, k.x), oy = k.y - tgtShip.y;
        const u = clamp2(ox * c + oy * sn, -L2 * 0.35, L2 * 0.35), hb = hbAt(u / L2 + 0.5, tgtShip.def.beam) * 0.7;
        const v = clamp2(-ox * sn + oy * c, -hb, hb);
        tx = game.world.wx(tgtShip.x + u * c - v * sn);
        ty = tgtShip.y + u * sn + v * c;
      }
      const dx = game.world.dx(k.x, tx), dy = ty - k.y;
      const d = Math.hypot(dx, dy);
      k.facing = Math.atan2(dy, dx);
      k.intent.mx = 0;
      k.intent.my = 0;
      if (d > 60) {
        k.alive = false;
        return;
      }
      this.t -= dt;
      if (!k.action && d > 4) {
        k.intent.mx = dx / d;
        k.intent.my = dy / d;
      }
      if (this.t <= 0 && d < 7) {
        this.t = 3 + Math.random() * 2;
        const bite = Math.random() < 0.6;
        game.fx.telegraph(tx, ty, "circle", { r: bite ? 2.6 : 4, life: 0.9, color: "rgba(255,40,40,1)" });
        k.action = { def: { anim: "heavy", steps: [], windup: 0.9, recover: 0.6 }, t: 0, step: 0, total: 1.6, mult: 1, angle: k.facing };
        setTimeout(() => {
          if (!k.alive || k.state !== "idle") return;
          const dmg = (bite ? 60 : 40) * (1 + k.attrs.str / 25);
          game.combat.hitbox({ owner: k, x: tx, y: ty - 0.4, shape: "circle", range: bite ? 2.6 : 4, damage: dmg * 0.5, knockback: 10, stun: 0.6, heavy: true, duration: 0.1, radial: true });
          if (tgtShip && hullGap(tgtShip, game.world.dx(tgtShip.x, tx), ty - tgtShip.y) < 2.5) tgtShip.damage(dmg, k);
          game.fx.burst(tx, ty, 30, { color: ["#e1f5fe", "#81d4fa", "#ffffff"], speed: 6, vz: 7, g: 12, life: 0.9, size: 0.22 });
          game.fx.shake(0.6);
          game.audio?.sfx("crash", { x: tx, y: ty });
        }, 900);
      }
    }
  };
  function drawSeaKing(g, env) {
    const t = env.time + this.seed;
    const col = this.bodyColor;
    const f = this.facing;
    const n = 7;
    for (let i = n - 1; i >= 0; i--) {
      const bx = -Math.cos(f) * i * 1.1 + Math.sin(t * 2 + i) * 0.3 * Math.sin(f);
      const by = -Math.sin(f) * i * 0.8 + Math.sin(t * 2 + i) * 0.3 * Math.cos(f);
      const hump = Math.max(0, Math.sin(t * 1.5 - i * 0.9)) * 0.8 + (i === 0 ? 1.6 : 0.2);
      g.fillStyle = "rgba(255,255,255,0.35)";
      g.beginPath();
      g.ellipse(bx, by, 1.1 - i * 0.08, 0.4, 0, 0, TAU);
      g.fill();
      g.fillStyle = col;
      g.beginPath();
      g.ellipse(bx, by - hump, 0.9 - i * 0.07, 0.75 - i * 0.05, 0, 0, TAU);
      g.fill();
      g.fillStyle = "rgba(255,255,255,0.15)";
      g.beginPath();
      g.ellipse(bx - 0.2, by - hump - 0.25, 0.4, 0.2, 0, 0, TAU);
      g.fill();
    }
    const hx = 0, hy = -2.6;
    g.fillStyle = col;
    g.beginPath();
    g.ellipse(hx, hy, 1.3, 1, 0, 0, TAU);
    g.fill();
    g.fillStyle = "#fff";
    g.beginPath();
    g.arc(hx - 0.45, hy - 0.25, 0.22, 0, TAU);
    g.arc(hx + 0.45, hy - 0.25, 0.22, 0, TAU);
    g.fill();
    g.fillStyle = "#b71c1c";
    g.beginPath();
    g.arc(hx - 0.45, hy - 0.22, 0.1, 0, TAU);
    g.arc(hx + 0.45, hy - 0.22, 0.1, 0, TAU);
    g.fill();
    g.fillStyle = "#3e2723";
    g.beginPath();
    g.ellipse(hx, hy + 0.4, 0.8, 0.3 + (this.action ? 0.25 : 0), 0, 0, TAU);
    g.fill();
    g.fillStyle = "#fff";
    for (let k = -3; k <= 3; k++) {
      g.beginPath();
      g.moveTo(hx + k * 0.2, hy + 0.2);
      g.lineTo(hx + k * 0.2 + 0.08, hy + 0.45);
      g.lineTo(hx + k * 0.2 + 0.16, hy + 0.2);
      g.fill();
    }
    if (this.state === "idle") {
      g.fillStyle = "rgba(0,0,0,0.6)";
      g.fillRect(-1.2, -4.2, 2.4, 0.16);
      g.fillStyle = "#ef5350";
      g.fillRect(-1.2, -4.2, 2.4 * Math.max(0, this.hp / this.d.maxHp), 0.16);
      g.font = "bold 0.34px Nunito, sans-serif";
      g.textAlign = "center";
      g.fillStyle = "#fff";
      g.strokeStyle = "#000";
      g.lineWidth = 0.06;
      g.strokeText(this.name, 0, -4.35);
      g.fillText(this.name, 0, -4.35);
    }
  }

  // src/content/helpers.js
  function spawnNow(game, id, pos) {
    const def = npcDef(id);
    if (!def) return null;
    const existing = findActor(game, id);
    if (existing) return existing;
    const isl = game.world.islands.find((i) => i.id === def.island);
    const list = game.spawner.populated.get(def.island);
    if (!list && !pos) return null;
    let p = pos;
    const at4 = typeof def.at === "function" ? def.at(game.state?.char, game) : def.at;
    if (!p && isl) {
      const s = at4?.spot && isl.spots[at4.spot];
      p = s ? game.spawner.findFree(s.x, s.y, 4) : at4 && (at4.town || at4.dock || at4.door || at4.building || at4.plaza || at4.dx !== void 0) ? placeFor(game, isl, def) : game.spawner.findFree(game.player.x + 4, game.player.y, 6);
    }
    if (!p) p = { x: game.player.x + 4, y: game.player.y };
    const a = makeNPC(def, p.x, p.y);
    a.game = game;
    game.addActor(a);
    if (list) list.push(a);
    return a;
  }
  function findActor(game, id) {
    return game.actors.find((a) => a.alive && a.npcId === id) || null;
  }
  function despawn(game, id) {
    const a = findActor(game, id);
    if (a) a.alive = false;
  }
  function aggro(game, a) {
    if (!a) return;
    a.provoked = true;
    a.aggroPlayer = true;
    if (a.controller) {
      a.controller.kind = "hostile";
      a.controller.target = game.player;
      a.controller.state = "chase";
    }
    a.stationary = false;
    if (a.boss) game.bossTarget = a;
  }
  function seaBoss(game, opts, x, y) {
    const k = makeSeaKing(game, x, y, opts.level, { ...opts, boss: true, hpMul: opts.hpMul || 4 });
    k.boss = true;
    game.addActor(k);
    game.bossTarget = k;
    return k;
  }
  function spawnGroup(game, grp) {
    const isl = game.world.islands.find((i) => i.id === grp.island);
    if (!isl) return [];
    const base2 = grp.spot ? isl.spots[grp.spot] : grp.x !== void 0 ? { x: grp.x, y: grp.y } : { x: isl.x + (grp.dx || 0) * isl.def.w / 2, y: isl.y + (grp.dy || 0) * isl.def.h / 2 };
    if (!base2) return [];
    const out = [];
    const list = game.spawner.populated.get(isl.id);
    for (const e of grp.enemies || []) {
      const [arch, lvl, over] = Array.isArray(e) ? e : [e, grp.level || 6, {}];
      const p = game.spawner.findFree(base2.x, base2.y, grp.radius || 5) || base2;
      const a = makeEnemy(arch, lvl, p.x, p.y, over || {});
      a.game = game;
      if (grp.leash) a.controller.leash = grp.leash;
      if (grp.aggro) aggro(game, a);
      game.addActor(a);
      if (list) list.push(a);
      out.push(a);
    }
    return out;
  }

