      dialogue: (ctx) => ({ start: "a", nodes: { a: { text: () => ctx.flag("yosakuCured") ? `"Never felt better! Scurvy, huh? I'll never skip my fruit again."` : '"(Yosaku lies pale on the deck, groaning. His gums are bleeding.)"' } } })
