      look: { hair: "short", hairColor: "#795548", skin: "#e0ac7e", top: "#5d4037", bottom: "#3e2723", hat: "tricorne", hatColor: "#4e342e", goggles: true },
      level: 17,
      faction: "pirate",
      style: "sniper",
      weapon: "gun",
