  function rollDice(c, callEven) {
    if (!c.pay(1e3)) return "broke";
    const a = 1 + Math.floor(Math.random() * 6), b = 1 + Math.floor(Math.random() * 6);
    const even = (a + b) % 2 === 0;
    c.char.flags.wbLastRoll = `${a} and ${b} \u2014 ${even ? "ch\u014D" : "han"}`;
    if (even === callEven) {
      c.earn(2e3, "ch\u014D-han");
      return "win";
    }
    return "lose";
  }
