      island: "sabaody",
      at: { town: "sabaody_grove41", building: "Takoyaki Hachi" },
      race: "fishman",
      look: { hair: "curly", hairColor: "#e53935", skin: "#ef9a9a", top: "#ffeb3b", bottom: "#5d4037" },
      level: 30,
